// EDIT THESE VALUES ONCE, then activate the workflow
return [{ json: {
  "sheetId": "PASTE_SHEET_ID",
  "business": "Your Business",
  "fromName": "Your Name",
  "phone": "(555) 000-0000",
  "offer": "$50 off your next service for you AND your friend",
  "daysAfterJob": 14
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

return $input.all().map(i => i.json).filter(r => String(r['Status']).toLowerCase() === 'done' && r['Email'] && !r['Referral sent'] && parse(r['Completed']) && days(parse(r['Completed']), today) >= C.daysAfterJob)
  .map(r => { const first = String(r['Customer']||'').split(' ')[0] || 'there';
    return { json: { row_number: r.row_number, email: r['Email'], subject: `A small thank-you from ${C.business}`,
      body: `Hi ${first},\n\nWe hope everything is still working great since our visit. Most of our customers find us through friends and neighbors, so if you know someone who needs help, we'd be grateful for an introduction.\n\nAs a thank-you: ${C.offer}. Just have them mention your name, or reply with their contact and we'll reach out.\n\nThank you,\n${C.fromName} · ${C.phone}` } }; });
